#include <stdio.h>

int main() {
    int n;
    /* &n 是「n 的地址」，scanf 需要知道往哪儿存 */
    scanf("%d", &n);
    printf("%d\n", n);
    return 0;
}

#include <stdio.h>

int main() {
    int a, b;
    scanf("%d %d", &a, &b);
    /* 直接把表达式写在 printf 里也可以 */
    printf("%d\n", a + b);
    return 0;
}

