#include <stdio.h>

int main() {
    int a, b;
    scanf("%d %d", &a, &b);

    /* 借助临时变量交换，三步的顺序不能颠倒 */
    int tmp = a;
    a = b;
    b = tmp;

    printf("%d\n%d\n", a, b);
    return 0;
}

