#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);
    /* 一次 printf 输出三行：格式串里的 \n 决定换行位置 */
    printf("%d\n%d\n%d\n", n, n * n, n * n * n);
    return 0;
}

#include <stdio.h>

int main() {
    int c;
    scanf("%d", &c);

    /* 关键：9.0 是浮点数，整个表达式才会按小数运算。
       写成 9 / 5 的话 C 会做整数除法，得到 1。 */
    double f = c * 9.0 / 5 + 32;
    printf("%.2f\n", f);
    return 0;
}
